mapper.select:
SELECT COUNT(*)
FROM TB_PM08M01 M
WHERE 1=1

AND M.HOLIDAY_DT <= #{holidayDtTo}
AND M.HOLIDAY_DT >= #{holidayDtFrom}


AND  = #{reqStatus}


AND  = #{resultStatus}


AND M.REQ_ID = #{reqId}


AND (EXISTS (SELECT 1 FROM TB_CM06M01 U WHERE U.ID = M.REQ_ID AND U.NAME LIKE '%' || #{reqNm} || '%') OR M.REQ_NM LIKE '%' || #{reqNm} || '%')


AND M.DEPT_ID = #{deptId}


AND EXISTS (SELECT 1 FROM TB_CM04M01 D WHERE D.DEPT_ID = M.DEPT_ID AND D.DEPT_NM LIKE '%' || #{deptNm} || '%')

SELECT * FROM ( SELECT ROWNUM AS RNUM, T.* FROM ( SELECT M.CO_CD, M.REQ_NO, M.REQ_ID, U.NAME AS REQ_NM, M.DEPT_ID, D.DEPT_NM, TO_CHAR(TO_DATE(M.HOLIDAY_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS HOLIDAY_DT, M.HOLIDAY_DT AS SUBSTITUTE_DT, M.ST_TM, M.ED_TM, NULL AS TOTAL_TM, (SELECT LISTAGG(SALES_CD, ', ') WITHIN GROUP (ORDER BY SEQ) FROM TB_PM08D01 WHERE REQ_NO = M.REQ_NO) AS SALES_CD, (SELECT LISTAGG(CLNT_NM, ', ') WITHIN GROUP (ORDER BY SEQ) FROM TB_PM08D01 WHERE REQ_NO = M.REQ_NO) AS CLNT_NM, (SELECT LISTAGG(PJT_NM, ', ') WITHIN GROUP (ORDER BY SEQ) FROM TB_PM08D01 WHERE REQ_NO = M.REQ_NO) AS PJT_NM, M.SPECIAL_REASON, M.REAL_ST_TM, M.REAL_ED_TM, NULL AS REAL_TOTAL_TM, M.WORK_RESULT, AS REQ_STATUS, AS RESULT_STATUS, M.CREAT_ID, TO_CHAR(M.CREAT_DTTM, 'YYYY-MM-DD HH24:MI:SS') AS CREAT_DTTM FROM TB_PM08M01 M LEFT JOIN TB_CM06M01 U ON U.ID = M.REQ_ID LEFT JOIN TB_CM04M01 D ON D.DEPT_ID = M.DEPT_ID WHERE 1=1
AND M.HOLIDAY_DT <= #{holidayDtTo} AND M.HOLIDAY_DT >= #{holidayDtFrom}
AND M.REQ_ID = #{reqId}
AND (U.NAME LIKE '%' || #{reqNm} || '%' OR M.REQ_NM LIKE '%' || #{reqNm} || '%')
AND M.DEPT_ID = #{deptId}
AND D.DEPT_NM LIKE '%' || #{deptNm} || '%'
AND = #{reqStatus}
AND = #{resultStatus}
ORDER BY M.HOLIDAY_DT DESC, M.REQ_NO DESC ) T
WHERE ROWNUM <= #{lastIndex}
)
WHERE RNUM >= #{firstIndex}

SELECT COUNT(*)
FROM TB_PM08M01
WHERE CO_CD = #{coCd, jdbcType=VARCHAR}
  AND REQ_ID = #{reqId, jdbcType=VARCHAR}
  AND HOLIDAY_DT = REPLACE(#{holidayDt, jdbcType=VARCHAR}, '-', '')

  AND REQ_NO != #{excludeReqNo, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM TB_PM08M01
WHERE CO_CD = #{coCd}
  AND REQ_NO = #{reqNo}

mapper.select:
SELECT COUNT(*)
FROM TB_WB20M03
WHERE TODO_NO = #{reqNo}
  AND TODO_DIV1_CODE_ID = 'TODODIV20'
  AND TODO_DIV2_CODE_ID = #{todoDiv2CodeId}

mapper.insert:
