	REQ_NO, SEQ, ORDRS_NO, SALES_CD, CO_CD, PJT_CD, PJT_NM, EQP_NM, CLNT_CD, CLNT_NM, ETC
) VALUES (
	#{reqNo}, NVL((SELECT MAX(SEQ) FROM TB_PM08D01 WHERE REQ_NO = #{reqNo}), 0) + 1,
	#{ordrsNo, jdbcType=VARCHAR}, #{salesCd, jdbcType=VARCHAR}, #{coCd, jdbcType=VARCHAR}, #{pjtCd, jdbcType=VARCHAR}, #{pjtNm, jdbcType=VARCHAR}, #{eqpNm, jdbcType=VARCHAR},
	#{clntCd, jdbcType=VARCHAR}, #{clntNm, jdbcType=VARCHAR}, #{etc, jdbcType=VARCHAR}
)

mapper.select:
SELECT COUNT(*)
  FROM TB_WB20M03
 WHERE TODO_NO = #{reqNo}

   AND TODO_DIV2_CODE_ID = #{todoDiv2CodeId}

   AND SANCTN_SN > 1
   AND SANCTN_STTUS = 'Y'

SELECT A.USER_ID, A.USER_NM, A.DEPT_NM, A.LEVEL_NM, NVL(V.SW_SUM, 0) AS GRANT_DAYS, (NVL(U2.VAC_M01,0)+NVL(U2.VAC_M02,0)+NVL(U2.VAC_M03,0)+NVL(U2.VAC_M04,0)+NVL(U2.VAC_M05,0)+NVL(U2.VAC_M06,0)+ NVL(U2.VAC_M07,0)+NVL(U2.VAC_M08,0)+NVL(U2.VAC_M09,0)+NVL(U2.VAC_M10,0)+NVL(U2.VAC_M11,0)+NVL(U2.VAC_M12,0)) AS USED_DAYS, (NVL(V.SW_SUM, 0) - (NVL(U2.VAC_M01,0)+NVL(U2.VAC_M02,0)+NVL(U2.VAC_M03,0)+NVL(U2.VAC_M04,0)+NVL(U2.VAC_M05,0)+NVL(U2.VAC_M06,0)+ NVL(U2.VAC_M07,0)+NVL(U2.VAC_M08,0)+NVL(U2.VAC_M09,0)+NVL(U2.VAC_M10,0)+NVL(U2.VAC_M11,0)+NVL(U2.VAC_M12,0)) ) AS BALANCE_DAYS, NVL(V.SW_M01, '') AS SW_M01, NVL(V.SW_M02, '') AS SW_M02, NVL(V.SW_M03, '') AS SW_M03, NVL(V.SW_M04, '') AS SW_M04, NVL(V.SW_M05, '') AS SW_M05, NVL(V.SW_M06, '') AS SW_M06, NVL(V.SW_M07, '') AS SW_M07, NVL(V.SW_M08, '') AS SW_M08, NVL(V.SW_M09, '') AS SW_M09, NVL(V.SW_M10, '') AS SW_M10, NVL(V.SW_M11, '') AS SW_M11, NVL(V.SW_M12, '') AS SW_M12, NVL(V.SW_SUM, 0) AS SW_SUM, NVL(U2.VAC_M01, 0) AS VAC_M01, NVL(U2.VAC_M02, 0) AS VAC_M02, NVL(U2.VAC_M03, 0) AS VAC_M03, NVL(U2.VAC_M04, 0) AS VAC_M04, NVL(U2.VAC_M05, 0) AS VAC_M05, NVL(U2.VAC_M06, 0) AS VAC_M06, NVL(U2.VAC_M07, 0) AS VAC_M07, NVL(U2.VAC_M08, 0) AS VAC_M08, NVL(U2.VAC_M09, 0) AS VAC_M09, NVL(U2.VAC_M10, 0) AS VAC_M10, NVL(U2.VAC_M11, 0) AS VAC_M11, NVL(U2.VAC_M12, 0) AS VAC_M12, NVL(U2.VAC_DAY_M01, '') AS VAC_DAY_M01, NVL(U2.VAC_DAY_M02, '') AS VAC_DAY_M02, NVL(U2.VAC_DAY_M03, '') AS VAC_DAY_M03, NVL(U2.VAC_DAY_M04, '') AS VAC_DAY_M04, NVL(U2.VAC_DAY_M05, '') AS VAC_DAY_M05, NVL(U2.VAC_DAY_M06, '') AS VAC_DAY_M06, NVL(U2.VAC_DAY_M07, '') AS VAC_DAY_M07, NVL(U2.VAC_DAY_M08, '') AS VAC_DAY_M08, NVL(U2.VAC_DAY_M09, '') AS VAC_DAY_M09, NVL(U2.VAC_DAY_M10, '') AS VAC_DAY_M10, NVL(U2.VAC_DAY_M11, '') AS VAC_DAY_M11, NVL(U2.VAC_DAY_M12, '') AS VAC_DAY_M12, NVL(U3.ANN_SUM, 0) AS ANN_SUM, NVL(U3.ANN_DAY_M01, '') AS ANN_DAY_M01, NVL(U3.ANN_DAY_M02, '') AS ANN_DAY_M02, NVL(U3.ANN_DAY_M03, '') AS ANN_DAY_M03, NVL(U3.ANN_DAY_M04, '') AS ANN_DAY_M04, NVL(U3.ANN_DAY_M05, '') AS ANN_DAY_M05, NVL(U3.ANN_DAY_M06, '') AS ANN_DAY_M06, NVL(U3.ANN_DAY_M07, '') AS ANN_DAY_M07, NVL(U3.ANN_DAY_M08, '') AS ANN_DAY_M08, NVL(U3.ANN_DAY_M09, '') AS ANN_DAY_M09, NVL(U3.ANN_DAY_M10, '') AS ANN_DAY_M10, NVL(U3.ANN_DAY_M11, '') AS ANN_DAY_M11, NVL(U3.ANN_DAY_M12, '') AS ANN_DAY_M12, NVL(W.WORK_TOT_M01, 0) AS WORK_TOT_M01, NVL(W.WORK_TOT_M02, 0) AS WORK_TOT_M02, NVL(W.WORK_TOT_M03, 0) AS WORK_TOT_M03, NVL(W.WORK_TOT_M04, 0) AS WORK_TOT_M04, NVL(W.WORK_TOT_M05, 0) AS WORK_TOT_M05, NVL(W.WORK_TOT_M06, 0) AS WORK_TOT_M06, NVL(W.WORK_TOT_M07, 0) AS WORK_TOT_M07, NVL(W.WORK_TOT_M08, 0) AS WORK_TOT_M08, NVL(W.WORK_TOT_M09, 0) AS WORK_TOT_M09, NVL(W.WORK_TOT_M10, 0) AS WORK_TOT_M10, NVL(W.WORK_TOT_M11, 0) AS WORK_TOT_M11, NVL(W.WORK_TOT_M12, 0) AS WORK_TOT_M12, NVL(W.WORK_OT_M01, 0) AS WORK_OT_M01, NVL(W.WORK_OT_M02, 0) AS WORK_OT_M02, NVL(W.WORK_OT_M03, 0) AS WORK_OT_M03, NVL(W.WORK_OT_M04, 0) AS WORK_OT_M04, NVL(W.WORK_OT_M05, 0) AS WORK_OT_M05, NVL(W.WORK_OT_M06, 0) AS WORK_OT_M06, NVL(W.WORK_OT_M07, 0) AS WORK_OT_M07, NVL(W.WORK_OT_M08, 0) AS WORK_OT_M08, NVL(W.WORK_OT_M09, 0) AS WORK_OT_M09, NVL(W.WORK_OT_M10, 0) AS WORK_OT_M10, NVL(W.WORK_OT_M11, 0) AS WORK_OT_M11, NVL(W.WORK_OT_M12, 0) AS WORK_OT_M12, NVL(X.RPT_HOUR_M01, 0) AS RPT_HOUR_M01, NVL(X.RPT_HOUR_M02, 0) AS RPT_HOUR_M02, NVL(X.RPT_HOUR_M03, 0) AS RPT_HOUR_M03, NVL(X.RPT_HOUR_M04, 0) AS RPT_HOUR_M04, NVL(X.RPT_HOUR_M05, 0) AS RPT_HOUR_M05, NVL(X.RPT_HOUR_M06, 0) AS RPT_HOUR_M06, NVL(X.RPT_HOUR_M07, 0) AS RPT_HOUR_M07, NVL(X.RPT_HOUR_M08, 0) AS RPT_HOUR_M08, NVL(X.RPT_HOUR_M09, 0) AS RPT_HOUR_M09, NVL(X.RPT_HOUR_M10, 0) AS RPT_HOUR_M10, NVL(X.RPT_HOUR_M11, 0) AS RPT_HOUR_M11, NVL(X.RPT_HOUR_M12, 0) AS RPT_HOUR_M12 FROM ( SELECT U.ID AS USER_ID, U.EMP_NO, U.NAME AS USER_NM, SUBSTR(NVL(U.VIEW_DEPT_ID, U.DEPT_ID), 1, 5) AS DEPT_ID, D.DEPT_NM, NVL(D.SORT_NO, 999) AS SORT_NO, (SELECT LEVEL_NM FROM TB_CM07M01 WHERE LEVEL_CD = U.LEVEL_CD) AS LEVEL_NM FROM TB_CM06M01 U LEFT JOIN TB_CM04M01 D ON D.DEPT_ID = SUBSTR(NVL(U.VIEW_DEPT_ID, U.DEPT_ID), 1, 5) WHERE 1=1 AND (NVL(U.VIEW_DEPT_ID, U.DEPT_ID) IS NULL OR (NVL(U.VIEW_DEPT_ID, U.DEPT_ID) NOT LIKE 'GUN95%' AND NVL(U.VIEW_DEPT_ID, U.DEPT_ID) NOT LIKE 'GUN00%')) AND (D.DEPT_NM IS NULL OR D.DEPT_NM NOT LIKE '%임원실%') AND (U.SALES_AREA IS NULL OR U.SALES_AREA != 'SALESAREA00')
AND U.USE_YN = #{useYn_S}
AND SUBSTR(NVL(U.VIEW_DEPT_ID, U.DEPT_ID), 1, 5) = SUBSTR(#{deptCd_S}, 1, 5)
AND D.DEPT_NM LIKE '%' || #{deptNm_S} || '%'
AND (U.NAME LIKE '%' || #{userNm_S} || '%' OR U.ID LIKE '%' || #{userNm_S} || '%')
AND U.ID = #{userId_S}
) A LEFT JOIN ( SELECT REQ_ID, COUNT(*) AS SW_SUM, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '01' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M01, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '02' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M02, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '03' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M03, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '04' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M04, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '05' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M05, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '06' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M06, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '07' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M07, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '08' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M08, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '09' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M09, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '10' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M10, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '11' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M11, LISTAGG(CASE WHEN SUBSTR(HOLIDAY_DT, 5, 2) = '12' THEN SUBSTR(HOLIDAY_DT, 7, 2) || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY HOLIDAY_DT) AS SW_M12 FROM TB_PM08M01 WHERE CO_CD = #{coCd} AND HOLIDAY_DT >= #{yy} || '0101' AND HOLIDAY_DT <= #{yy} || '1231' GROUP BY REQ_ID ) V ON A.USER_ID = V.REQ_ID LEFT JOIN ( SELECT REQ_ID, NVL(SUM(CASE WHEN VAC_MONTH = '01' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M01, NVL(SUM(CASE WHEN VAC_MONTH = '02' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M02, NVL(SUM(CASE WHEN VAC_MONTH = '03' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M03, NVL(SUM(CASE WHEN VAC_MONTH = '04' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M04, NVL(SUM(CASE WHEN VAC_MONTH = '05' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M05, NVL(SUM(CASE WHEN VAC_MONTH = '06' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M06, NVL(SUM(CASE WHEN VAC_MONTH = '07' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M07, NVL(SUM(CASE WHEN VAC_MONTH = '08' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M08, NVL(SUM(CASE WHEN VAC_MONTH = '09' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M09, NVL(SUM(CASE WHEN VAC_MONTH = '10' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M10, NVL(SUM(CASE WHEN VAC_MONTH = '11' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M11, NVL(SUM(CASE WHEN VAC_MONTH = '12' THEN DEDUCT_DAYS ELSE 0 END), 0) AS VAC_M12, LISTAGG(CASE WHEN VAC_MONTH = '01' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M01, LISTAGG(CASE WHEN VAC_MONTH = '02' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M02, LISTAGG(CASE WHEN VAC_MONTH = '03' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M03, LISTAGG(CASE WHEN VAC_MONTH = '04' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M04, LISTAGG(CASE WHEN VAC_MONTH = '05' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M05, LISTAGG(CASE WHEN VAC_MONTH = '06' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M06, LISTAGG(CASE WHEN VAC_MONTH = '07' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M07, LISTAGG(CASE WHEN VAC_MONTH = '08' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M08, LISTAGG(CASE WHEN VAC_MONTH = '09' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M09, LISTAGG(CASE WHEN VAC_MONTH = '10' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M10, LISTAGG(CASE WHEN VAC_MONTH = '11' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M11, LISTAGG(CASE WHEN VAC_MONTH = '12' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS VAC_DAY_M12 FROM (
SELECT DAYS.REQ_ID, DAYS.REQ_NO, DAYS.VAC_DT, SUBSTR(DAYS.VAC_DT, 5, 2) AS VAC_MONTH, SUBSTR(DAYS.VAC_DT, 7, 2) AS VAC_DAY, DAYS.DEDUCT_DAYS FROM ( SELECT M.REQ_ID, M.REQ_NO, TO_CHAR(TO_DATE(M.ST_DT, 'YYYYMMDD') + (LEVEL - 1), 'YYYYMMDD') AS VAC_DT, (M.DEDUCT_DAYS / (TO_DATE(M.ED_DT, 'YYYYMMDD') - TO_DATE(M.ST_DT, 'YYYYMMDD') + 1)) AS DEDUCT_DAYS FROM TB_PM07M01 M WHERE M.VAC_TYPE_CD IN ('PM07TYPE11', 'PM07TYPE12') AND NVL(M.SANCTN_STS, 'TEMP') != 'RTN' AND M.ST_DT IS NOT NULL AND M.ED_DT IS NOT NULL AND M.ST_DT <= #{yy} || '1231' AND M.ED_DT >= #{yy} || '0101' CONNECT BY LEVEL <= (TO_DATE(M.ED_DT, 'YYYYMMDD') - TO_DATE(M.ST_DT, 'YYYYMMDD') + 1) AND PRIOR M.REQ_NO = M.REQ_NO AND PRIOR DBMS_RANDOM.VALUE IS NOT NULL ) DAYS WHERE SUBSTR(DAYS.VAC_DT, 1, 4) = #{yy} ) DD GROUP BY REQ_ID ) U2 ON A.USER_ID = U2.REQ_ID LEFT JOIN (
SELECT REQ_ID, NVL(SUM(DEDUCT_DAYS), 0) AS ANN_SUM, LISTAGG(CASE WHEN VAC_MONTH = '01' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M01, LISTAGG(CASE WHEN VAC_MONTH = '02' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M02, LISTAGG(CASE WHEN VAC_MONTH = '03' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M03, LISTAGG(CASE WHEN VAC_MONTH = '04' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M04, LISTAGG(CASE WHEN VAC_MONTH = '05' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M05, LISTAGG(CASE WHEN VAC_MONTH = '06' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M06, LISTAGG(CASE WHEN VAC_MONTH = '07' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M07, LISTAGG(CASE WHEN VAC_MONTH = '08' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M08, LISTAGG(CASE WHEN VAC_MONTH = '09' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M09, LISTAGG(CASE WHEN VAC_MONTH = '10' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M10, LISTAGG(CASE WHEN VAC_MONTH = '11' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M11, LISTAGG(CASE WHEN VAC_MONTH = '12' THEN VAC_DAY || ':' || REQ_NO END, ',') WITHIN GROUP (ORDER BY VAC_DT) AS ANN_DAY_M12 FROM ( SELECT DAYS3.REQ_ID, DAYS3.REQ_NO, DAYS3.VAC_DT, SUBSTR(DAYS3.VAC_DT, 5, 2) AS VAC_MONTH, SUBSTR(DAYS3.VAC_DT, 7, 2) AS VAC_DAY, DAYS3.DEDUCT_DAYS FROM ( SELECT M.REQ_ID, M.REQ_NO, TO_CHAR(TO_DATE(M.ST_DT, 'YYYYMMDD') + (LEVEL - 1), 'YYYYMMDD') AS VAC_DT, (M.DEDUCT_DAYS / (TO_DATE(M.ED_DT, 'YYYYMMDD') - TO_DATE(M.ST_DT, 'YYYYMMDD') + 1)) AS DEDUCT_DAYS FROM TB_PM07M01 M WHERE M.VAC_TYPE_CD IN ('PM07TYPE01', 'PM07TYPE02') AND NVL(M.SANCTN_STS, 'TEMP') != 'RTN' AND M.ST_DT IS NOT NULL AND M.ED_DT IS NOT NULL AND M.ST_DT <= #{yy} || '1231' AND M.ED_DT >= #{yy} || '0101' CONNECT BY LEVEL <= (TO_DATE(M.ED_DT, 'YYYYMMDD') - TO_DATE(M.ST_DT, 'YYYYMMDD') + 1) AND PRIOR M.REQ_NO = M.REQ_NO AND PRIOR DBMS_RANDOM.VALUE IS NOT NULL ) DAYS3 WHERE SUBSTR(DAYS3.VAC_DT, 1, 4) = #{yy} ) DD3 GROUP BY REQ_ID ) U3 ON A.USER_ID = U3.REQ_ID LEFT JOIN ( SELECT EMP_NO, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '01' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M01, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '02' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M02, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '03' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M03, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '04' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M04, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '05' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M05, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '06' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M06, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '07' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M07, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '08' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M08, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '09' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M09, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '10' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M10, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '11' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M11, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '12' THEN NVL(TO_NUMBER(NULLIF(REPLACE(TOT_WORK_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_TOT_M12, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '01' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M01, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '02' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M02, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '03' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M03, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '04' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M04, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '05' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M05, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '06' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M06, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '07' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M07, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '08' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M08, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '09' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M09, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '10' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M10, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '11' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M11, NVL(SUM(CASE WHEN SUBSTR(WORK_DT, 5, 2) = '12' THEN NVL(TO_NUMBER(NULLIF(REPLACE(OT_TM, ':', '.'), '')), 0) ELSE 0 END), 0) AS WORK_OT_M12 FROM TB_PM30M01 WHERE CO_CD = #{coCd} AND WORK_DT >= #{yy} || '0101' AND WORK_DT <= #{yy} || '1231' GROUP BY EMP_NO ) W ON A.EMP_NO = W.EMP_NO LEFT JOIN ( SELECT WORK_RPT_ID, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '01' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M01, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '02' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M02, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '03' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M03, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '04' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M04, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '05' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M05, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '06' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M06, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '07' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M07, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '08' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M08, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '09' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M09, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '10' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M10, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '11' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M11, NVL(SUM(CASE WHEN TO_CHAR(WORK_RPT_DT, 'MM') = '12' THEN NVL(WORK_RPT_HOUR, 0) ELSE 0 END), 0) AS RPT_HOUR_M12 FROM TB_PM01M01 WHERE CO_CD = #{coCd} AND WORK_RPT_DT >= TO_DATE(#{yy} || '0101', 'YYYYMMDD') AND WORK_RPT_DT < TO_DATE(#{yy} || '1231', 'YYYYMMDD') + 1 GROUP BY WORK_RPT_ID ) X ON A.USER_ID = X.WORK_RPT_ID ORDER BY A.SORT_NO ASC, A.DEPT_NM ASC, A.USER_NM ASC
